package com.yeyamo_mobile.api.booking_service.infrastructure.messaging;import java.util.UUID;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.booking_service.application.BookingApplicationService;
@Component public class PaymentEventConsumer{private final ObjectMapper mapper;private final BookingApplicationService service;private final ProcessedEventRepository processed;public PaymentEventConsumer(ObjectMapper m,BookingApplicationService s,ProcessedEventRepository p){mapper=m;service=s;processed=p;}@KafkaListener(topics="${yeyamo.kafka.topics.payment-events:payment.events}",groupId="${spring.kafka.consumer.group-id:booking-service}")@Transactional public void consume(String raw)throws Exception{JsonNode e=mapper.readTree(raw);UUID eventId=UUID.fromString(required(e,"eventId"));if(processed.existsById(eventId))return;if(e.path("eventVersion").asInt(0)!=1)throw new IllegalArgumentException("Unsupported event version");String type=required(e,"eventType");JsonNode p=e.path("payload");if(!"BOOKING".equals(text(p,"sourceType"))){processed.save(new ProcessedEventEntity(eventId,type));return;}String correlation=text(e,"correlationId");switch(type){case"payment.authorized"->service.paymentAuthorized(eventId,source(p),required(p,"paymentId"),correlation);case"payment.failed"->service.paymentFailed(eventId,source(p),optional(p,"reason","Payment authorization failed"),correlation);case"payment.refunded"->service.paymentRefunded(eventId,source(p),correlation);default->{}}processed.save(new ProcessedEventEntity(eventId,type));}private UUID source(JsonNode p){return UUID.fromString(required(p,"sourceId"));}private String optional(JsonNode n,String f,String fallback){String value=text(n,f);return value==null||value.isBlank()?fallback:value;}private String required(JsonNode n,String f){String value=text(n,f);if(value==null||value.isBlank())throw new IllegalArgumentException(f+" is required");return value;}private String text(JsonNode n,String f){JsonNode value=n.get(f);return value==null||value.isNull()?null:value.asText();}}
